import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.ArrayList;
import java.util.List;

public class DirectoryBacktracker {

    public List<Path> findFilesWithBacktracking(Path rootDir, String targetSuffix) throws IOException {
        List<Path> results = new ArrayList<>();
        explore(rootDir, targetSuffix, results);
        return results;
    }

    private void explore(Path currentPath, String targetSuffix, List<Path> results) throws IOException {
        if (!Files.exists(currentPath) || !Files.isDirectory(currentPath)) {
            return;
        }

        try (var stream = Files.list(currentPath)) {
            for (Path path : (Iterable<Path>) stream::iterator) {
                if (Files.isDirectory(path)) {
                    // Choice: Enter subdirectory (Recursive step)
                    explore(path, targetSuffix, results);
                    // Backtrack implicit here as we pop back out of the stack frame
                } else if (path.toString().endsWith(targetSuffix)) {
                    // Goal reached: Record valid state
                    results.add(path);
                }
            }
        } catch (AccessDeniedException e) {
            // Backtracking safety: Prune the search tree on permission failure
            System.err.println("Skipping restricted directory: " + currentPath);
        }
    }
}
